const REQUIRED = {
  ADD_LEAD: ['business_name'],
  LIST_LEADS: [],
  GET_LEAD: ['business_name'],
  UPDATE_LEAD: ['business_name'],
  CHANGE_STATUS: ['business_name', 'status'],
  UPDATE_DEAL_VALUE: ['business_name', 'deal_value'],
  DELETE_LEAD: ['business_name'],
  DELETE_ALL_LEADS: [],
  DELETE_EVERYTHING: [],
  RECORD_INTERACTION: ['business_name'],
  ADD_NOTE: ['business_name', 'notes'],
  GET_LEAD_HISTORY: ['business_name'],
  DELETE_ALL_INTERACTIONS: [],
  CREATE_FOLLOW_UP: ['business_name'],
  COMPLETE_FOLLOW_UP: ['business_name'],
  UPDATE_FOLLOW_UP: ['business_name'],
  CANCEL_FOLLOW_UP: ['business_name'],
  LIST_FOLLOW_UPS: [],
  DELETE_FOLLOW_UP: ['business_name'],
  DELETE_ALL_FOLLOWUPS: [],
  AMBIGUOUS_DELETE: ['business_name'],
  DAILY_PRIORITY: [],
  PIPELINE_ANALYTICS: [],
  REVENUE_ANALYTICS: [],
  LEAD_ANALYTICS: [],

  // LEVEL 12 — Standalone Notes
  ADD_STANDALONE_NOTE: ['content'],
  LIST_STANDALONE_NOTES: [],
  DELETE_STANDALONE_NOTE: ['note_id'],
  DELETE_ALL_STANDALONE_NOTES: [],

  // LEVEL 13 — Standalone Reminders
  CREATE_REMINDER: ['reminder_text', 'follow_up_date'],
  LIST_REMINDERS: [],
  DELETE_REMINDER: ['reminder_id'],
  DELETE_ALL_REMINDERS: [],

  // LEVEL 14 — Personal Daily Tasks
  CREATE_DAILY_TASKS: ['tasks'],
  LIST_TASKS: [],
  ADD_TASK: ['task_name'],
  UPDATE_TASK: ['task_id'],
  COMPLETE_TASK: ['task_id'],
  DELETE_TASK: ['task_id'],
  DELETE_ALL_TASKS: [],

  UNKNOWN: []
};

const ALLOWED_STATUS = ['NEW','CONTACTED','REPLIED','QUALIFIED','PROPOSAL_SENT','NEGOTIATION','WON','LOST'];

// Maps common phrasing Gemini might return to the exact enum value the DB expects.
const STATUS_ALIASES = {
  'PROPOSAL': 'PROPOSAL_SENT',
  'PROPOSAL SENT': 'PROPOSAL_SENT',
  'SENT PROPOSAL': 'PROPOSAL_SENT',
  'SEND PROPOSAL': 'PROPOSAL_SENT',
  'CONTACT': 'CONTACTED',
  'REPLY': 'REPLIED',
  'REPLIED TO': 'REPLIED',
  'QUALIFY': 'QUALIFIED',
  'NEGOTIATE': 'NEGOTIATION',
  'NEGOTIATING': 'NEGOTIATION',
  'WIN': 'WON',
  'CLOSED WON': 'WON',
  'LOSE': 'LOST',
  'CLOSED LOST': 'LOST',
  'NEW LEAD': 'NEW'
};

const trig = $('Build Gemini Request').first().json;
const chatId = trig.chatId;
const userId = trig.userId;
const text = trig.text;
const messageId = trig.messageId;
const callbackQueryId = trig.callbackQueryId;
const callbackData = trig.callbackData;
const updateId = trig.updateId;

let parsed = null;
try {
  const raw = $input.first().json;
  const candidate = raw.candidates && raw.candidates[0];
  if (raw.error || !candidate || !candidate.content || !candidate.content.parts) throw new Error('gemini_error');
  let rawText = candidate.content.parts.map(p => p.text || '').join('');
  rawText = rawText.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  parsed = JSON.parse(rawText);
} catch (e) {
  return [{
    json: {
      chatId,
      userId,
      text,
      messageId,
      callbackQueryId,
      callbackData,
      updateId,
      command: 'UNKNOWN',
      confidence: 0,
      parameters: {},
      missing: [],
      systemError: true
    }
  }];
}

let command = typeof parsed.command === 'string' ? parsed.command.toUpperCase().trim() : 'UNKNOWN';
if (!(command in REQUIRED)) command = 'UNKNOWN';

let confidence = typeof parsed.confidence === 'number' ? parsed.confidence : 0;
let parameters = (parsed.parameters && typeof parsed.parameters === 'object') ? parsed.parameters : {};

if (parameters.status) {
  let s = String(parameters.status).toUpperCase().trim();
  if (STATUS_ALIASES[s]) s = STATUS_ALIASES[s];
  parameters.status = s;
  if (!ALLOWED_STATUS.includes(parameters.status)) {
    parameters._invalidStatus = parameters.status;
    delete parameters.status;
  }
}

if (parameters.deal_value !== undefined) {
  const v = Number(String(parameters.deal_value).toString().replace(/[^0-9.\-]/g, ''));
  parameters.deal_value = isNaN(v) ? undefined : v;
}

// Standalone notes field normalization
if (command === 'ADD_STANDALONE_NOTE') {
  if (!parameters.content && parameters.notes) parameters.content = parameters.notes;
  if (!parameters.content && text) parameters.content = text;
}

// Standalone reminders field normalization
if (command === 'CREATE_REMINDER') {
  if (parameters.due_at && !parameters.follow_up_date) parameters.follow_up_date = parameters.due_at;
  if (parameters.follow_up_date && !parameters.due_at) parameters.due_at = parameters.follow_up_date;
  if (!parameters.reminder_text && parameters.content) parameters.reminder_text = parameters.content;
  if (!parameters.reminder_text && parameters.notes) parameters.reminder_text = parameters.notes;
}

// Daily tasks field normalization
if (command === 'CREATE_DAILY_TASKS') {
  if (typeof parameters.tasks === 'string') {
    parameters.tasks = parameters.tasks.split('\n').map(t => t.trim().replace(/^[-*•0-9.)\s]+/, '')).filter(Boolean);
  }
}

if (parameters.priority) {
  parameters.priority = String(parameters.priority).toUpperCase().trim();
}

const missing = (REQUIRED[command] || []).filter(f => {
  const val = parameters[f];
  if (val === undefined || val === null || val === '') return true;
  if (Array.isArray(val) && val.length === 0) return true;
  return false;
});

return [{
  json: {
    chatId,
    userId,
    text,
    messageId,
    callbackQueryId,
    callbackData,
    updateId,
    command,
    confidence,
    parameters,
    missing,
    systemError: false
  }
}];
